.seckill-box{
	background: #fff

	.hd{
		display: flex
		justify-content: space-between
		align-items: center
		background-repeat: no-repeat;
		background-size: 100% 100%;
		width: 100%;
		height: 48px;
		padding: 0 12px;
		.right{
			color: #fff;
			font-size: 12px;
			.iconfont{
				font-size: 12px;
			}
		}
		.left{
			display: flex
			align-items: center
			.text{
				font-size: 16px;
				margin-right: 8px
			}
			.line{
				width: 1px;
				height: 10px;
				background: #DDDDDD;
				margin: 0 9px;
			}
			img{
				width: 70px
				height: 16px
			}
			.tips {
				font-size: 13px
				color: #fff
				font-weight:400;
			}
		}
	}
	.list-wrapper{
		display: flex;
		justify-content: center;
		overflow: hidden;
		padding: 10px;
		width: 100%;
		&.on{
			display: block;
		}
		&.on2{
			flex-wrap: wrap;
			justify-content: flex-start;
		}
		&.on3{
			justify-content: flex-start;
			padding-right: 0;
		}
		.itemTwo,.itemThree{
			width: 48%;
			position: relative;
			margin-right: 11px;
			margin-top: 15px;

			.item{
				height: 50px;
			}

			.item2{
				height: 30px;
			}

			&:nth-child(1){
				margin-top: 0;
			}

			&:nth-child(2){
				margin-top: 0;
			}

			&:nth-of-type(2n){
				margin-right: 0;
			}

			.empty-box{
				width: 100%;
				height: 162px;
				background-color: #F3F9FF;
				img{
					width: 64px;
					height: 50px;
					display: block
				}
			}
			.title{
				font-size: 14px;
				color: #333333;
				margin-top: 8px;
			}
			.price{
				font-weight: 600;
				font-size: 12px;
				&.on{
					margin-top: 4px;
				}
				.num{
					font-size: 15px;
				}
			}
			.yprice{
				font-size: 11px;
				text-decoration: line-through;
				&.on{
					margin-top: 9px;
				}
			}
			.bnt{
				width: 57px;
				height: 26px;
				border-radius: 13px;
				text-align: center;
				line-height: 26px;
				position: absolute;
				right: 0;
				bottom:0;
				font-size: 12px;
				color: #FFFFFF;
				&.on{
					bottom:-4px;
				}
				&.on2{
					bottom:6px;
				}
			}
		}

		.itemThree{
			width: 112px;
			margin-top: 0;
			margin-right: 10px !important;
			.item{
				height: 45px;
			}
			.item2{
				height: 29px;
			}
			.empty-box{
				height: 112px;
				width: 112px;
			}
			.title{
				font-size: 13px;
				margin-top: 6px;
			}
			.price{
				font-size: 11px;
				margin-top: 3px;
				font-weight: 400;
				&.on{
					margin-top: 6px;
				}
				.num{
					font-weight: 600
				}
				.label{
					font-weight: 600
					margin-left: 4px;
				}
			}
		}

		.itemOne{
			position: relative;

			&~.itemOne{
				margin-top: 15px;
			}
			.empty-box{
				width: 120px;
				height: 120px;
				margin-right: 12px;
				background-color: #F3F9FF;
				img{
					width: 65px;
					height: 50px;
					display: block
				}
			}
			.text{
				flex: 1;
				.top{
					height: 77px;
				}
				.bottom{
					.bnt{
						width: 203px;
						height: 34px;
						background: #E93323;
						border-radius: 4px;
						margin-top: 8px;
						overflow: hidden;
						.bntCon{
							background:rgba(255,255,255,0.9);
							position: relative;
							border-radius: 4px;
							overflow: hidden;
							img {
								width: 24px;
								height: 42px;
								display: block;
								position: absolute;
								top:-1px;
								left:50%;
								margin-left: -10px;
							}
							.left{
								width: 50%;
								font-size: 11px;
								color: #E93323;
								line-height: 34px;
								padding-left: 10px;
							}
							.right{
								width: 50%;
								line-height: 33px;
								text-align: center;
								font-size: 13px;
								font-family: Alimama ShuHeiTi, Alimama ShuHeiTi;
								font-weight: 700;
								color: #fff;
							}
						}
					}
				}
				.name{
					font-size: 14px;
					color: #333333;
					margin-bottom: 8px;
				}
				.price{
					font-size: 11px;
					color: #E93323;
					.label{
						font-weight: 600;
						margin-left: 4px;
					}
					.num{
						font-size: 16px;
						font-weight: 600;
					}
				}
			}
		}

		.list-item{
			width: 31.47%;
			margin-top: 10px;

			&~.list-item{
				margin-left: 9px;
			}

			&:nth-of-type(3n-2){
				margin-left: 0;
			}

			&:nth-child(1),&:nth-child(2),&:nth-child(3){
				margin-top: 0;
			}

			.img-box{
				border-radius: 6px;
				position: relative;
				width: 100%
				height: 106px;

				.empty-box{
					background-color: #F3F9FF;
					img{
						width: 65px;
						height: 50px;
						display: block;
					}
				}
			}
			.title{
				margin-top: 8px
				font-size: 13px
				color: #333
			}
			.price{
				position: relative;
				color: #fff;
				font-size: 11px;

				.lable{
					font-size: 11px;
					font-weight: 600;
					margin-left: 2px;
				}

				.num{
					font-size: 15px;
					font-weight: 600;
				}

				img{
					width: 12px;
					height: 22px;
					display: block;
					position: absolute;
					left:-4px;
					top:0
				}
			}
			.yprice{
				color: #999;
				font-size: 12px;
				text-decoration: line-through;
			}
		}
	}
}
